// FILLING IN THE KEPT SCRAMBLES on a set priced before the column existed.
// It is a USER function and not a script somebody remembers to run (RULE FIVE
// and RULE NINE), so it lives here with the set it changes, says what the set
// has now, and prints what the choice costs BEFORE the button is pressed.
function bKeptFillPanel(doc) {
  if (doc.stage !== 3) return '';
  const p = doc.params || {};
  const nullN = Number(p.nullN) || 0;
  const have = Number(p.keepN) || 0;
  // SIZED FROM THE ROWS ON DISK, not from the plan. The plan is what the LAUNCH
  // asked for; a set that has since been filled in holds more than that, and on
  // the owner's set the difference is 329,280 against 524,832 per unit -- so a
  // cost printed from the plan understates a four-hour job by nearly half.
  const rows = Number((doc.counts || {}).rows) || 0;
  const off = doc.status !== 'done';
  // THE BOX STARTS ON WHAT THE SET ALREADY KEEPS (owner order, 2026-09-02:
  // "that button better not run and start deleting good data if it gets hit
  // again"). A press at that number is refused by the fill; only a number
  // ABOVE it does anything, and that asks first (wireKeptFill).
  const want = have || Math.min(10, nullN);
  // the same arithmetic the fill itself does: the real test money once as a
  // proof, then each ADDED scramble on each of the two windows -- a top-up
  // prices only the scrambles the records do not hold
  const cost = (k) => rows * (1 + Math.max(0, k - have) * 2);
  return `<div class="panel">
      <h3 style="margin-top:0">Filling in the kept null money</h3>
      <div class="row" style="align-items:flex-end">
        <label class="f" title="how many of this set's null-set deals should have their money written down, so the Funnel has a whole second copy of Table 3.A and Table 3.B made of scrambled money to measure against. It re-prices only what is missing, never the whole run, and it proves itself against the money already stored before anything is swapped.">null set money kept<input id="bKeptN" type="number" value="${want}" min="0" max="${nullN}" data-have="${have}" data-rows="${rows}" style="width:4.5rem" ${off ? 'disabled' : ''}></label>
      </div>
      <div class="row">
        <button id="bKeptGo" ${off ? 'disabled title="the set is still working — a fill waits until it has landed"' : ''}>Fill in the kept null money</button>
      <span id="bKeptMsg" class="note">${have ? `this set keeps ${have} of its ${nullN}. Pressing at ${have} does nothing; a higher number adds only the missing scrambles and asks first.` : `this set keeps none of its ${nullN}.`}${nullN && rows && !have ? ` Keeping ${want} re-prices ${cost(want).toLocaleString()} times, across ${rows.toLocaleString()} rows.` : ''}</span>
</div>
    </div>`;
}
// THE DATE RANGES A RUN USED, ON ITS HEADER (3.85.0, owner order 2026-09-07).
// Each window is the span across the run's units; the unread window runs from
// where the seal began to the newest candle the box holds today, because
// whatever reads it reads all the data there is.
function windowsLineHtml(win) {
  if (!win) return '';
  const day = (ts) => (Number.isFinite(ts) ? new Date(ts).toISOString().slice(0, 10) : '?');
  const rng = (w) => (w ? `${day(w.fromTs)} → ${day(w.toTs)}` : null);
  const parts = [];
  if (win.train) parts.push(`training ${rng(win.train)}`);
  if (win.test) parts.push(`test ${rng(win.test)}`);
  if (win.hold) parts.push(`held-back ${rng(win.hold)}`);
  if (win.unread) parts.push(`unread from ${day(win.unread.fromTs)} onward — the box holds data to ${day(win.unread.dataToTs)}, all of it unread`);
  // a run still going, or paused, has them for the units priced so far
  const state = win.known >= win.units && win.units > 0 ? '' : win.known ? ` — ${win.known} of ${win.units} units so far` : '';
  return `<p class="note"><b>Date ranges:</b> ${parts.length ? parts.map((x) => esc(x)).join(' · ') : (win.units ? 'not recorded on this run yet' : 'no units')}${state}</p>`;
}
function runIdentityPanelHtml(sizeLine, dm, win = null) {
  return `<div class="panel"><h3 style="margin-top:0">What this run actually is</h3>
          ${sizeLine || ''}
          ${windowsLineHtml(win)}
          <!-- dm.overallDigest / dm.symbols / dm.at are what lib/manifest.js
               actually writes. This read dm.digest, dm.coins, dm.files and
               dm.utc — four names nothing has ever written — so the fingerprint
               that decides whether two runs are comparable at all rendered as
               "—" with no coin or file count and no stamp time, on every run
               that had one (audit 2026-08-17). -->
          ${dm ? `<p class="note"><b>Data fingerprint:</b> <code>${esc(String(dm.overallDigest || dm.error || '—')).slice(0, 24)}</code>
            ${dm.symbols ? `· ${Object.keys(dm.symbols).length} coin(s), ${Object.values(dm.symbols).reduce((a, x) => a + (x.files || 0), 0)} file(s)` : ''}
            ${dm.at ? `· stamped ${esc(String(dm.at).slice(0, 16))}` : ''}
            <span title="taken at launch, over every candle file this run read. Two runs are data-comparable exactly when these match — a different fingerprint means the cache moved between the fire times.">(?)</span>
            ${dm.error ? ' <b class="warn">STAMP FAILED — this run cannot be proved comparable to any other</b>' : ''}</p>` : ''}
          </div>`;
}
// One save wiring for both screens; only the address differs. Re-render from
// the RESPONSE: the stored value comes back truncated, and the edited stamp
// is taken on the server, not here. onSaved lets a screen refresh its own
// cached copy (Boards keeps the opened run's doc in hand).
function wireKeptFill(id) {
  const go = $('#bKeptGo');
  if (!go) return;
  go.onclick = async () => {
    const keep = Number(($('#bKeptN') || {}).value) || 0;
    // RAISING THE COUNT IS ASKED FIRST, with what it costs. A fill runs for
    // hours and puts the page to sleep at its end; a mis-typed 11 must not
    // start one on a slip. The refusal for a number at or below what the set
    // keeps is the fill's own and needs no asking.
    const bx = $('#bKeptN');
    const haveNow = Number((bx && bx.dataset.have) || 0);
    const rowsNow = Number((bx && bx.dataset.rows) || 0);
    if (haveNow && keep > haveNow) {
      const adding = keep - haveNow;
      const msg = `This set already keeps ${haveNow} scrambles. Add ${adding} more, for ${keep} in all?\n\n`
        + `Only the ${adding} missing scramble(s) are priced -- ${(rowsNow * (1 + adding * 2)).toLocaleString()} pricings across ${rowsNow.toLocaleString()} rows -- `
        + 'and the records are rewritten beside and swapped only after every check passes. Hours, not minutes.';
      if (!confirm(msg)) return;
    }
    go.disabled = true;
    // THE WAIT BOX, RAISED BEFORE THE ASK (owner, 2026-09-01: "it sits for 30
    // seconds looking like it didn't get the button click").
    //
    // This press is slow for a real reason: the answer does not come back until
    // the pass has worked out every setting the set declares, and on the
    // owner's board that is 524,832 of them. Half a minute of a page that looks
    // exactly like a page that ignored you is how a second press happens, and a
    // second press is a second refusal.
    //
    // waitStart/waitEnd, not a box of my own: it is the same one every slow
    // redraw on this page raises, it counts rather than flags so two slow
    // things at once cannot uncover each other, and it shows itself late so a
    // fast answer never flashes it. `finally`, because a refusal must uncover
    // the page too.
    waitStart();
    let out;
    try {
      out = await tryPost(`api/stageset/${encodeURIComponent(id)}/kept-fill`, { keep });
    } finally {
      waitEnd();
    }
    // tryPost already says why on a refusal; re-enable so the owner can change
    // the number and ask again rather than being left with a dead button
    if (!out) { go.disabled = false; return; }
    $('#bKeptMsg').textContent = `filling in ${out.keep} across ${out.units} unit(s) — `
      + `${Number(out.pricings).toLocaleString()} pricings.`;
    // STRAIGHT TO WHERE THE PROGRESS ACTUALLY IS (owner order, 2026-08-31).
    // The fill runs for hours and reports on the Sweep section's status line,
    // not on this one, so a press that leaves the owner here leaves them
    // watching a line that will never move again.
    //
    // The top is reached through the page's OWN scroll memory rather than a
    // scrollTo of my own. Every redraw restores the tab's remembered place two
    // frames later, so a hand-rolled scroll would be undone right after it
    // happened. Setting Sweep's memory to the top and then restoring it uses
    // that mechanism instead of racing it -- and it leaves the memory honest,
    // because the page really is at the top afterwards.
    rememberScroll(tab);                     // keep the owner's place on the one being left
    try { localStorage.setItem(scrollKeyFor('sweep'), '0'); } catch (_) { /* private window */ }
    tab = 'sweep';
    bHeldBack = false;
    localStorage.setItem('cx-tab', tab);
    draw().then(() => restoreScroll(tab));
  };
}
// the rename posts the one field the endpoint reads, then redraws Boards where
// it stands, because every picker and heading on the screen shows the name
function wireRename(url, suffix) {
  const b = $(`#bRename${suffix}`);
  if (b) b.onclick = async () => {
    const box = $(`#bName${suffix}`);
    const out = await tryPost(url, { name: box.value });
    if (out) {
      box.value = out.name || '';
      $(`#bNameMsg${suffix}`).textContent = `renamed ${String(out.nameEditedAt || '').slice(0, 16)}`;
      drawBoardsHoldingPlace();
    }
  };
}
function wireNotesSave(saveUrl, onSaved, suffix) {
  const nsave = $(`#bNotesSave${suffix}`);
  if (nsave) nsave.onclick = async () => {
    const box = $(`#bNotes${suffix}`);
    const out = await tryPost(saveUrl, { text: box.value });
    if (out) {
      box.value = out.notes || '';
      $(`#bNotesMsg${suffix}`).textContent = `saved ${String(out.notesEditedAt || '').slice(0, 16)}`;
      if (onSaved) onSaved(out);
    }
  };
}

// ---- Held and Reserve: the verdict on a Stage 4 record set, on one stretch each --------
//
// (3.86.0, VERIFY-DESIGN.md; two tabs off one renderer since 3.147.0, Part 9.)
// ONE RENDERER, THE STRETCH AS ITS ONLY PARAMETER. drawHeld and drawReserve
// are one line each; everything they draw is drawJudge(stretch) and the
// helpers below, so the two tabs cannot drift apart (RULE TWO's shape). Every
// place the code asks which stretch it is on is a deliberate difference: the
// words for the window, which rules the box lists, and the confirm before a
// press that prices.
//
// A PRESS MAKES A SET. Reading a rule on a stretch writes a held set or a
// reserve set of the rule, named after it, numbered from the second press;
// the sets already made are drawn under the press, newest first, the newest
// in full. The three readings under them belong to the rule, per stretch.
const JUDGE_SET_KEY = { held: 'cx-held-set', reserve: 'cx-reserve-set' };
// THE STRETCH'S OWN WORDS, WHOLE. A label that differs by stretch is written as
// two whole phrases, each wrapped in a tag, because the word list's walk keeps
// a quoted string as page text only when it carries a tag and reads the text
// between tags as one name -- so "Read the rule on the held-back window" lands
// on the list whole, and so does its Reserve twin, on both tabs. Both ARE on
// both screens: Reserve names the held set it stands on, Held says when a
// layout keeps no reserve. stretchWindow() is the one noun phrase every
// sentence here shares; hover text and confirm boxes take stretchPlain(),
// which carries no tag.
function stretchWindow(stretch) { return stretch === 'reserve' ? '<span>reserve window</span>' : '<span>held-back window</span>'; }
function stretchPlain(stretch) { return stretch === 'reserve' ? 'reserve' : 'held-back'; }
function tabWord(stretch) { return stretch === 'reserve' ? 'Reserve' : 'Held'; }
function vRememberedSet(list, stretch) {
  let want = null;
  try { want = localStorage.getItem(JUDGE_SET_KEY[stretch]); } catch (_) { want = null; }
  if (want && list.some((x) => x.id === want)) return want;
  return list.length ? list[0].id : null;          // newest first, as the server lists them
}
const vDay = (ts) => (ts != null && Number.isFinite(Number(ts)) ? new Date(Number(ts)).toISOString().slice(0, 10) : '?');
const vPct = (v) => (v == null ? '?' : `${Math.round(100 * v)}%`);
const vFix = (v, n = 2) => (v == null || !Number.isFinite(Number(v)) ? 'none' : Number(v).toFixed(n));

// A SET'S NAME WITH ITS COIN AND SHAPE, SAID ONCE (3.142.3, owner: "is there a
// good reason this one's so ugly"): a set named after its coin and shape was
// printed with them twice in every set box. The unit is added only when the
// name does not already carry it. Braces on purpose (see the History note).
function setNameWords(x) {
  const unit = x.unitName || 'all units together';
  return rebuildPrefix(x) + (String(x.name || '').includes(unit) ? esc(x.name) : `${esc(x.name)} · ${esc(unit)}`);
}
// REBUILD REQUIRED IN FRONT OF THE NAME (3.235.0, owner 2026-09-23: "flag
// somehow all the data sets that need a rebuild. Maybe put a prefix on
// them"): wherever a set is listed or opened, the words go before the name
// the owner gave it while the service says the set carries a reason; the name
// itself is never changed, and the words go when the set is rebuilt.
function rebuildPrefix(x) { return x && x.rebuild ? 'REBUILD REQUIRED - ' : ''; }
function rebuildLineHtml(x) {
  if (!x || !x.rebuild) return '';
  const rb = x.rebuild;
  const stage4 = (rb.reasons || []).some((r) => r.key === 'stage4');
  // an opened set that stands on figures worked out at the standard size is
  // rebuilt the first time it is opened (3.236.0), once a visit: the press is
  // made after this line is on the screen, and its answer is said in it
  if (stage4 && x.id) setTimeout(() => rebuildOnOpen(x.id), 0);
  // REPAIR (3.248.0): a survivor by depth chosen the old way is chosen again as the set is opened
  if ((rb.reasons || []).some((r) => r.key === 'pick') && x.id) setTimeout(() => repickOnOpen(x.id), 0);
  const now = rb.failed ? ` · <b class="neg">the rebuild stopped: ${esc(rb.failed)}</b>` : (rb.running ? ` · rebuilding now: ${esc(rb.running)}` : '');
  return `<p class="note"><b class="warn">REBUILD REQUIRED</b> - ${(rb.reasons || []).map((r) => esc(r.why)).join(' · ')}<span data-rebuild-say="${esc(x.id || '')}">${now}</span></p>`;
}
function rebuildOnOpen(id) {
  if (rebuiltThisVisit.has(`stage4|${id}`)) return;
  rebuiltThisVisit.add(`stage4|${id}`);
  const url = `api/funnel/set/${encodeURIComponent(id)}/rebuild-required`;
  const say = (words) => document.querySelectorAll(`[data-rebuild-say="${CSS.escape(id)}"]`).forEach((el) => { el.textContent = words ? ` · ${words}` : ''; });
  const sayOf = (r) => (r.failed ? `the rebuild stopped: ${r.failed}` : r.error ? `the rebuild stopped: ${r.error}`
    : r.done ? 'rebuilt - choose it again to see it' : r.waiting ? r.words : (r.words ? `rebuilding now: ${r.words}` : ''));
  // its line follows the rebuild where it stands, and the screen is never drawn again for it
  const follow = () => api(url).then((r) => {
    if (r.none) return;
    say(sayOf(r));
    if (r.running || r.waiting) setTimeout(follow, 20000);
  }).catch(() => setTimeout(follow, 60000));
  // pressed once a visit: a refusal is said in its own words and never pressed again
  post(url, {}).then((r) => {
    say(sayOf(r));
    if (r.running || r.waiting) setTimeout(follow, 20000);
  }).catch((e) => say(`the rebuild could not be started: ${e.message}`));
}
// ---- REPAIR (3.248.0), deleted with pickBehind in lib/stages.js (RULE TEN) ----
// The survivor by depth of a capture taken before 3.248.0 is chosen again by its
// neighbouring settings, once a visit, and the line says when it is done.
function repickOnOpen(id) {
  if (rebuiltThisVisit.has(`pick|${id}`)) return;
  rebuiltThisVisit.add(`pick|${id}`);
  const say = (words) => document.querySelectorAll(`[data-rebuild-say="${CSS.escape(id)}"]`).forEach((el) => { el.textContent = words ? ` · ${words}` : ''; });
  say('choosing its survivor by depth again');
  post(`api/funnel/set/${encodeURIComponent(id)}/repick`, {})
    .then((r) => say(r.done ? `its survivor by depth is now ${r.label || 'none'} - choose it again to see it` : ''))
    .catch((e) => say(`its survivor by depth could not be chosen again: ${e.message}`));
}
// ---- EVERY STAGE 4 RECORD SET BOX CARRIES THE SAME TWO THINGS (3.249.0) ----
//
// Owner order 2026-09-25: "i need a way to: 1. DELETE stage 4 record sets --
// they're multiplying like rabbits 2. FILTER (with a checkbox beside all of the
// Stage 4 record set selectors) on the currently selected campaign". The tick
// is ONE setting for every box: ticked on one tab, it is ticked on all of them,
// because the campaign it names is the one Sweep has set, and that is one
// thing. The delete is the one flow every record set is deleted through; a
// rule takes the held and reserve sets read from it along, and every read of
// the held-back or reserve window that goes is written onto a set of the same
// family, so it still counts as a look.
const S4_CAMP_KEY = 'cx-s4-campaign-only';
let s4CampNow = { name: '' };        // the campaign currently set on Sweep, as the tab being drawn last read it
async function s4CampRead() { s4CampNow = await apiOr('api/campaign', ({ name: '' })); return s4CampNow; }
function s4CampOn() { try { return localStorage.getItem(S4_CAMP_KEY) === '1'; } catch (_) { return false; } }
// the sets of the campaign set on Sweep while the tick is on; `keep` stays listed whatever it is (the Funnel's open set)
function s4CampList(list, keep = null) {
  const name = s4CampNow && s4CampNow.name;
  if (!s4CampOn() || !name) return list || [];
  return (list || []).filter((x) => x.campaign === name || (keep && x.id === keep));
}
function s4CampTickHtml() {
  const name = (s4CampNow && s4CampNow.name) || '';
  return `<label class="c" title="${name
    ? `ticked, the box beside this lists only the Stage 4 record sets whose stage 3 set was run under ${esc(name)}, the campaign currently set on Sweep. One tick for every Stage 4 record set box: ticked here, it is ticked on every tab.`
    : 'no campaign is currently set on Sweep, so there is no campaign to narrow the box to'}"><input type="checkbox" class="s4Camp"${s4CampOn() && name ? ' checked' : ''}${name ? '' : ' disabled'}> ${name ? `only campaign ${esc(name)}` : 'only the campaign currently set'}</label>`;
}
function s4CampWire(redraw) {
  document.querySelectorAll('.s4Camp').forEach((el) => {
    el.onchange = () => { try { localStorage.setItem(S4_CAMP_KEY, el.checked ? '1' : '0'); } catch (_) { /* private window */ } redraw(); };
  });
}
// the press, in a row of its own under the box (RULE FOUR-A), the same words as the Funnel's
function s4DeleteRowHtml(chosen) {
  return `<div class="row"><button class="danger s4Delete" ${chosen ? '' : 'disabled'} title="permanently deletes the Stage 4 record set chosen in the box above. A rule takes the held and reserve sets read from it along; every read of the held-back or reserve window that goes is written onto a set of the same family and still counts as a look. Refused while the set is being worked on, or while a greenlight written from it stands. Nothing is deleted until the set's id is typed back.">Delete Stage 4 record set…</button></div>`;
}
function s4DeleteWire(chosen, after) {
  if (!chosen) return;
  document.querySelectorAll('.s4Delete').forEach((b) => {
    b.onclick = async () => {
      b.disabled = true;
      const done = await deleteSetFlow(chosen);
      b.disabled = false;
      if (done) after(done);
    };
  });
}
// THE RULES A TAB LISTS (VERIFY-DESIGN.md Part 9): Held lists every rule, plain
// or half-life; Reserve lists only rules whose layout keeps a reserve and whose
// newest held set passed. Held sets and reserve sets are never listed here:
// they are what a press makes, and they are drawn under it.
function vRulesFor(sets, stretch) {
  const rules = (sets || []).filter((x) => (x.kind || 'funnel') === 'funnel');
  if (stretch === 'held') return rules;
  return rules.filter((x) => x.judge && x.judge.keepsReserve && x.judge.held && x.judge.held.stands);
}
// the set is picked from the server's own list, newest first, never typed.
// EACH RULE BY ITS NAME AND NOTHING ELSE (3.234.5, owner order 2026-09-23: "the
// mangled stage 4 record set name on the Held tab drop down at the top ...
