        cState.wF = { ...(cState.wF || {}), wholeOnly: 'yes' };
        cState.wFrom = 0;
        cShownFor = null;
        cSplitSaid = `${keys.length} row(s) promoted \u2014 the table above is showing those ${keys.length} rows and nothing else. `
          + 'Untick only the rows Choose early, read late is showing to widen it again.';
        cRemember();
        said.innerHTML = `<span class="pos">${keys.length} row(s) promoted \u2014 they are in the list at the top, and the table above is showing them</span>`;
